cat > /workspace/src/main.rs << 'EOF'
use std::fs;
use std::path::{Path, PathBuf};
use anyhow::{Context, Result};
use clap::Parser;
use log::{error, info};
use std::io::Read;

mod svd;
mod codegen;
mod cli;

use cli::Args;
use svd::parse::Parser as SvdParser;

fn main() {
    let args = Args::parse();

    // Initialize logger
    let log_level = args.log.unwrap_or(log::LevelFilter::Info);
    env_logger::Builder::from_default_env()
        .filter_level(log_level)
        .format_module_path(false)
        .format_target(false)
        .init();

    if let Err(e) = run(args) {
        error!("{:?}", e);
        std::process::exit(1);
    }
}

fn run(args: Args) -> Result<()> {
    info!("Parsing device from SVD file");

    // Read SVD file from stdin or file
    let svd_content = if let Some(input_file) = &args.input {
        fs::read_to_string(input_file)
            .context("Cannot open the SVD file")?
    } else {
        let mut buffer = String::new();
        std::io::stdin().read_to_string(&mut buffer)
            .context("Cannot read from stdin")?;
        buffer
    };

    // Parse SVD
    let parser = SvdParser::new();
    let device = parser.parse(&svd_content)?;

    info!("Rendering device");

    // Generate code
    let code = codegen::generate(&device, &args)?;

    // Write output
    if let Some(output_dir) = &args.output_dir {
        fs::create_dir_all(output_dir)
            .context("Cannot create output directory")?;

        let file_name = if args.make_mod { "mod.rs" } else { "lib.rs" };
        let output_file = output_dir.join(file_name);

        fs::write(&output_file, &code)
            .context(format!("Couldn't create output file: {}", output_file.display()))?;

        // Write build.rs and device.x
        let build_rs = include_str!("../templates/build.rs");
        fs::write(output_dir.join("build.rs"), build_rs)
            .context("Couldn't write build.rs")?;

        let device_x = include_str!("../templates/device.x");
        fs::write(output_dir.join("device.x"), device_x)
            .context("Couldn't write device.x")?;
    }

    Ok(())
}
EOF

