cat > /workspace/src/cli.rs << 'EOF'
use clap::Parser;
use std::path::PathBuf;
use log::LevelFilter;

#[derive(Parser, Debug)]
#[command(name = "svd2rust")]
#[command(version = "0.37.1 (e29353d 2026-03-03)")]
#[command(about = "Generate a Rust API from SVD files")]
#[command(long_about = None)]
pub struct Args {
    /// Input SVD file
    #[arg(short = 'i', value_name = "FILE")]
    pub input: Option<PathBuf>,

    /// Directory to place generated files
    #[arg(short = 'o', long = "output-dir", value_name = "PATH")]
    pub output_dir: Option<PathBuf>,

    /// Config TOML file
    #[arg(short = 'c', long = "config", value_name = "TOML_FILE")]
    pub config: Option<PathBuf>,

    /// Target-specific settings YAML file
    #[arg(long = "settings", value_name = "YAML_FILE")]
    pub settings: Option<PathBuf>,

    /// Rust edition of generated code
    #[arg(long = "edition", value_name = "YEAR")]
    pub edition: Option<String>,

    /// Target architecture
    #[arg(long = "target", value_name = "ARCH")]
    pub target: Option<String>,

    /// Generate atomic register modification API
    #[arg(long = "atomics")]
    pub atomics: bool,

    /// add feature gating for atomic register modification API
    #[arg(long = "atomics-feature", value_name = "FEATURE")]
    pub atomics_feature: Option<String>,

    /// Don't add alternateGroup name as prefix to register name
    #[arg(long = "ignore-groups")]
    pub ignore_groups: bool,

    /// Keep lists when generating code of dimElement, instead of trying to generate arrays
    #[arg(long = "keep-list")]
    pub keep_list: bool,

    /// Push generic mod in separate file
    #[arg(short = 'g', long = "generic-mod")]
    pub generic_mod: bool,

    /// Use group_name of peripherals as feature
    #[arg(long = "feature-group")]
    pub feature_group: bool,

    /// Use independent cfg feature flags for each peripheral
    #[arg(long = "feature-peripheral")]
    pub feature_peripheral: bool,

    /// Specify `-f type:prefix:case:suffix` to change default ident formatting
    #[arg(short = 'f', long = "ident-format", value_name = "ident_format")]
    pub ident_format: Option<String>,

    /// A set of `ident_format` settings. `new` or `legacy`
    #[arg(long = "ident-formats-theme", value_name = "THEME")]
    pub ident_formats_theme: Option<String>,

    /// Use field name for enumerations even when enumeratedValues has a name
    #[arg(long = "field-names-for-enums")]
    pub field_names_for_enums: bool,

    /// Use array increment for cluster size
    #[arg(long = "max-cluster-size")]
    pub max_cluster_size: bool,

    /// implement Debug for readable blocks and registers
    #[arg(long = "impl-debug")]
    pub impl_debug: bool,

    /// Add feature gating for block and register debug implementation
    #[arg(long = "impl-debug-feature", value_name = "FEATURE")]
    pub impl_debug_feature: Option<String>,

    /// Add automatic defmt implementation for enumerated values
    #[arg(long = "impl-defmt", value_name = "FEATURE")]
    pub impl_defmt: Option<String>,

    /// Create mod.rs instead of lib.rs, without inner attributes
    #[arg(short = 'm', long = "make-mod")]
    pub make_mod: bool,

    /// Do not generate crate attributes
    #[arg(long = "skip-crate-attributes")]
    pub skip_crate_attributes: bool,

    /// Make advanced checks due to parsing SVD
    #[arg(short = 's', long = "strict")]
    pub strict: bool,

    /// Specify file/stream format
    #[arg(long = "source-type", value_name = "source_type")]
    pub source_type: Option<String>,

    /// For Cortex-M target reexport peripherals from cortex-m crate
    #[arg(long = "reexport-core-peripherals")]
    pub reexport_core_peripherals: bool,

    /// Reexport interrupt macro from cortex-m-rt like crates
    #[arg(long = "reexport-interrupt")]
    pub reexport_interrupt: bool,

    /// Add offset to all base addresses on all peripherals in the SVD file
    #[arg(short = 'b', long = "base-address-shift", value_name = "base_address_shift")]
    pub base_address_shift: Option<u64>,

    /// Choose which messages to log (overrides RUST_LOG)
    #[arg(short = 'l', long = "log", value_name = "log_level")]
    pub log: Option<LevelFilter>,
}
EOF

