use super::schema::*;
use anyhow::{Context, Result};
use roxmltree::Document;

pub struct Parser;

impl Parser {
    pub fn new() -> Self {
        Parser
    }

    pub fn parse(&self, svd_content: &str) -> Result<Device> {
        let doc = Document::parse(svd_content)
            .context("Error parsing SVD XML file")?;

        let root = doc.root_element();
        if root.tag().name() != "device" {
            anyhow::bail!("Expected root element to be 'device'");
        }

        self.parse_device(root)
    }

    fn parse_device(&self, root: roxmltree::Node) -> Result<Device> {
        let name = self.get_text(root, "name")?;

        let peripherals_node = root.children()
            .find(|n| n.tag().map(|t| t.name()) == Some("peripherals"))
            .context(format!("Parsing device `{}` at {}:{}", name, root.range().start.line, root.range().start.col))?;

        let peripherals = self.parse_peripherals(peripherals_node)?;

        Ok(Device {
            name,
            version: self.get_optional_text(root, "version"),
            description: self.get_optional_text(root, "description"),
            address_unit_bits: self.get_text_as_u32(root, "addressUnitBits")
                .unwrap_or(8),
            max_nr_interrupts: self.get_text_as_u32(root, "maxNrInterrupts").ok(),
            vendor: self.get_optional_text(root, "vendor"),
            vendor_id: self.get_optional_text(root, "vendorID"),
            series: self.get_optional_text(root, "series"),
            contact: self.get_optional_text(root, "contact"),
            license: self.get_optional_text(root, "license"),
            license_text: self.get_optional_text(root, "licenseText"),
            peripherals,
        })
    }

    fn parse_peripherals(&self, node: roxmltree::Node) -> Result<Vec<Peripheral>> {
        let mut peripherals = Vec::new();

        for child in node.children().filter(|n| n.is_element()) {
            if child.tag().map(|t| t.name()) == Some("peripheral") {
                peripherals.push(self.parse_peripheral(child)?);
            }
        }

        Ok(peripherals)
    }

    fn parse_peripheral(&self, node: roxmltree::Node) -> Result<Peripheral> {
        let name = self.get_text(node, "name")?;
        let base_address = self.get_text_as_u64(node, "baseAddress")?;

        let mut registers = Vec::new();
        let mut clusters = Vec::new();

        if let Some(reg_node) = node.children().find(|n| n.tag().map(|t| t.name()) == Some("registers")) {
            for child in reg_node.children().filter(|n| n.is_element()) {
                match child.tag().map(|t| t.name()) {
                    Some("register") => registers.push(self.parse_register(child)?),
                    Some("cluster") => clusters.push(self.parse_cluster(child)?),
                    _ => {}
                }
            }
        }

        Ok(Peripheral {
            name,
            version: self.get_optional_text(node, "version"),
            description: self.get_optional_text(node, "description"),
            group_name: self.get_optional_text(node, "groupName"),
            base_address,
            size: self.get_text_as_u32(node, "size").ok(),
            access: self.get_optional_text(node, "access"),
            reset_value: self.get_text_as_u64(node, "resetValue").ok(),
            reset_mask: self.get_text_as_u64(node, "resetMask").ok(),
            address_blocks: self.parse_address_blocks(node),
            registers,
            clusters,
            interrupts: self.parse_interrupts(node),
        })
    }

    fn parse_address_blocks(&self, node: roxmltree::Node) -> Vec<AddressBlock> {
        let mut blocks = Vec::new();

        if let Some(ab_node) = node.children().find(|n| n.tag().map(|t| t.name()) == Some("addressBlock")) {
            for child in ab_node.children().filter(|n| n.is_element()) {
                if child.tag().map(|t| t.name()) == Some("addressBlock") {
                    if let (Ok(offset), Ok(size)) = (
                        self.get_text_as_u32(child, "offset"),
                        self.get_text_as_u32(child, "size"),
                    ) {
                        if let Some(usage) = self.get_optional_text(child, "usage") {
                            blocks.push(AddressBlock {
                                offset,
                                size,
                                usage,
                                protection: self.get_optional_text(child, "protection"),
                            });
                        }
                    }
                }
            }
        }

        blocks
    }

    fn parse_register(&self, node: roxmltree::Node) -> Result<Register> {
        let name = self.get_text(node, "name")?;
        let address_offset = self.get_text_as_u32(node, "addressOffset")?;

        let mut fields = Vec::new();
        if let Some(fields_node) = node.children().find(|n| n.tag().map(|t| t.name()) == Some("fields")) {
            for child in fields_node.children().filter(|n| n.is_element()) {
                if child.tag().map(|t| t.name()) == Some("field") {
                    fields.push(self.parse_field(child)?);
                }
            }
        }

        Ok(Register {
            name,
            display_name: self.get_optional_text(node, "displayName"),
            description: self.get_optional_text(node, "description"),
            address_offset,
            size: self.get_text_as_u32(node, "size").ok(),
            access: self.get_optional_text(node, "access"),
            reset_value: self.get_text_as_u64(node, "resetValue").ok(),
            reset_mask: self.get_text_as_u64(node, "resetMask").ok(),
            fields,
        })
    }

    fn parse_cluster(&self, node: roxmltree::Node) -> Result<Cluster> {
        let name = self.get_text(node, "name")?;
        let address_offset = self.get_text_as_u32(node, "addressOffset")?;

        let mut registers = Vec::new();
        if let Some(reg_node) = node.children().find(|n| n.tag().map(|t| t.name()) == Some("registers")) {
            for child in reg_node.children().filter(|n| n.is_element()) {
                if child.tag().map(|t| t.name()) == Some("register") {
                    registers.push(self.parse_register(child)?);
                }
            }
        }

        Ok(Cluster {
            name,
            description: self.get_optional_text(node, "description"),
            address_offset,
            size: self.get_text_as_u32(node, "size").ok(),
            registers,
        })
    }

    fn parse_field(&self, node: roxmltree::Node) -> Result<Field> {
        let name = self.get_text(node, "name")?;
        let bit_offset = self.get_text_as_u32(node, "bitOffset")?;
        let bit_width = self.get_text_as_u32(node, "bitWidth")?;

        let mut enumerated_values = Vec::new();
        if let Some(ev_node) = node.children().find(|n| n.tag().map(|t| t.name()) == Some("enumeratedValues")) {
            for child in ev_node.children().filter(|n| n.is_element()) {
                if child.tag().map(|t| t.name()) == Some("enumeratedValue") {
                    enumerated_values.push(self.parse_enumerated_value(child)?);
                }
            }
        }

        Ok(Field {
            name,
            description: self.get_optional_text(node, "description"),
            bit_offset,
            bit_width,
            access: self.get_optional_text(node, "access"),
            reset_value: self.get_text_as_u64(node, "resetValue").ok(),
            read_action: self.get_optional_text(node, "readAction"),
            modified_write_values: self.get_optional_text(node, "modifiedWriteValues"),
            write_constraint: None,
            enumerated_values,
        })
    }

    fn parse_enumerated_value(&self, node: roxmltree::Node) -> Result<EnumeratedValue> {
        Ok(EnumeratedValue {
            name: self.get_optional_text(node, "name"),
            description: self.get_optional_text(node, "description"),
            value: self.get_text_as_u64(node, "value").ok(),
            is_default: node.attribute("isDefault").map(|v| v == "true").unwrap_or(false),
        })
    }

    fn parse_interrupts(&self, node: roxmltree::Node) -> Vec<Interrupt> {
        let mut interrupts = Vec::new();

        if let Some(int_node) = node.children().find(|n| n.tag().map(|t| t.name()) == Some("interrupt")) {
            for child in int_node.children().filter(|n| n.is_element()) {
                if child.tag().map(|t| t.name()) == Some("interrupt") {
                    if let (Some(name), Ok(value)) = (
                        self.get_optional_text(child, "name"),
                        self.get_text_as_u32(child, "value"),
                    ) {
                        interrupts.push(Interrupt {
                            name,
                            value,
                            description: self.get_optional_text(child, "description"),
                        });
                    }
                }
            }
        }

        interrupts
    }

    // Helper functions
    fn get_text(&self, node: roxmltree::Node, tag_name: &str) -> Result<String> {
        node.children()
            .find(|n| n.tag().map(|t| t.name()) == Some(tag_name))
            .and_then(|n| n.text())
            .map(|s| s.to_string())
            .ok_or_else(|| anyhow::anyhow!("Missing tag: {}", tag_name))
    }

    fn get_optional_text(&self, node: roxmltree::Node, tag_name: &str) -> Option<String> {
        node.children()
            .find(|n| n.tag().map(|t| t.name()) == Some(tag_name))
            .and_then(|n| n.text())
            .map(|s| s.to_string())
    }

    fn get_text_as_u32(&self, node: roxmltree::Node, tag_name: &str) -> Result<u32> {
        let text = self.get_text(node, tag_name)?;
        u32::from_str_radix(text.trim_start_matches("0x").trim_start_matches("0X"), 16)
            .or_else(|_| text.parse::<u32>())
            .with_context(|| format!("Invalid u32 value in {}: {}", tag_name, text))
    }

    fn get_text_as_u64(&self, node: roxmltree::Node, tag_name: &str) -> Result<u64> {
        let text = self.get_text(node, tag_name)?;
        u64::from_str_radix(text.trim_start_matches("0x").trim_start_matches("0X"), 16)
            .or_else(|_| text.parse::<u64>())
            .with_context(|| format!("Invalid u64 value in {}: {}", tag_name, text))
    }
}
