            bit_width,
            access: self.get_optional_text(node, "access"),
            reset_value: self.get_text_as_u64(node, "resetValue").ok(),
            read_action: self.get_optional_text(node, "readAction"),
            modified_write_values: self.get_optional_text(node, "modifiedWriteValues"),
            write_constraint: None,
            enumerated_values,
        })
    }

    fn parse_enumerated_value(&self, node: roxmltree::Node) -> Result<EnumeratedValue> {
        Ok(EnumeratedValue {
            name: self.get_optional_text(node, "name"),
            description: self.get_optional_text(node, "description"),
            value: self.get_text_as_u64(node, "value").ok(),
            is_default: node.attribute("isDefault").map(|v| v == "true").unwrap_or(false),
        })
    }

    fn parse_interrupts(&self, node: roxmltree::Node) -> Vec<Interrupt> {
        let mut interrupts = Vec::new();

        if let Some(int_node) = node.children().find(|n| n.tag().map(|t| t.name()) == Some("interrupt")) {
            for child in int_node.children().filter(|n| n.is_element()) {
                if child.tag().map(|t| t.name()) == Some("interrupt") {
                    if let (Some(name), Ok(value)) = (
                        self.get_optional_text(child, "name"),
                        self.get_text_as_u32(child, "value"),
                    ) {
                        interrupts.push(Interrupt {
                            name,
                            value,
                            description: self.get_optional_text(child, "description"),
                        });
                    }
                }
            }
        }

        interrupts
    }

    // Helper functions
    fn get_text(&self, node: roxmltree::Node, tag_name: &str) -> Result<String> {
        node.children()
            .find(|n| n.tag().map(|t| t.name()) == Some(tag_name))
            .and_then(|n| n.text())
            .map(|s| s.to_string())
            .ok_or_else(|| anyhow::anyhow!("Missing tag: {}", tag_name))
    }

    fn get_optional_text(&self, node: roxmltree::Node, tag_name: &str) -> Option<String> {
        node.children()
            .find(|n| n.tag().map(|t| t.name()) == Some(tag_name))
            .and_then(|n| n.text())
            .map(|s| s.to_string())
    }

    fn get_text_as_u32(&self, node: roxmltree::Node, tag_name: &str) -> Result<u32> {
        let text = self.get_text(node, tag_name)?;
        u32::from_str_radix(text.trim_start_matches("0x").trim_start_matches("0X"), 16)
            .or_else(|_| text.parse::<u32>())
            .with_context(|| format!("Invalid u32 value in {}: {}", tag_name, text))
    }

    fn get_text_as_u64(&self, node: roxmltree::Node, tag_name: &str) -> Result<u64> {
        let text = self.get_text(node, tag_name)?;
        u64::from_str_radix(text.trim_start_matches("0x").trim_start_matches("0X"), 16)
            .or_else(|_| text.parse::<u64>())
            .with_context(|| format!("Invalid u64 value in {}: {}", tag_name, text))
    }
}
