use crate::cli::Args;
use crate::svd::schema::Device;
use anyhow::Result;

pub fn generate(device: &Device, args: &Args) -> Result<String> {
    let mut output = String::new();

    if !args.make_mod && !args.skip_crate_attributes {
        output.push_str("# ! [doc = \"Peripheral access API for ");
        output.push_str(&device.name);
        output.push_str(" microcontrollers (generated using svd2rust v0.37.1 (e29353d 2026-03-03))\\n\\n\
You can find an overview of the generated API [here].\\n\\n\
API features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n\
[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n\
[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n\
[repository]: https://github.com/rust-embedded/svd2rust\"]\n");
        output.push_str("# ! [allow (non_camel_case_types)]\n");
        output.push_str("# ! [allow (non_snake_case)]\n");
        output.push_str("# ! [no_std]\n");
        output.push_str("# ! [cfg_attr (docsrs , feature (doc_cfg))]\n");
    }

    output.push_str("#[allow (unused_imports)] use generic :: * ;\n");

    if args.generic_mod {
        output.push_str("#[doc = r\"Common register and bit access and modify traits\"]\npub mod generic;");
    } else {
        output.push_str("#[doc = r\"Common register and bit access and modify traits\"]\npub mod generic {\n");
        output.push_str(GENERIC_MODULE);
        output.push_str("\n}\n");
    }

    // Generate peripheral modules
    output.push_str("\n");
    for peripheral in &device.peripherals {
        output.push_str(&format!("#[doc = \"{}\"]\npub mod {} {{\n", 
            peripheral.description.as_ref().unwrap_or(&"".to_string()),
            peripheral.name.to_lowercase()));
        output.push_str("    use super::generic::*;\n");
        output.push_str("}\n");
    }

    Ok(output)
}

