use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct Element {
    pub name: String,
    pub attributes: HashMap<String, String>,
    pub text: String,
    pub children: Vec<Element>,
}

impl Element {
    pub fn new(name: String) -> Self {
        Element {
            name,
            attributes: HashMap::new(),
            text: String::new(),
            children: Vec::new(),
        }
    }

    pub fn get_child(&self, name: &str) -> Option<&Element> {
        self.children.iter().find(|c| c.name == name)
    }

    pub fn get_children(&self, name: &str) -> Vec<&Element> {
        self.children.iter().filter(|c| c.name == name).collect()
    }

    pub fn get_text(&self) -> &str {
        &self.text
    }

    pub fn get_attribute(&self, name: &str) -> Option<&str> {
        self.attributes.get(name).map(|s| s.as_str())
    }
}

pub fn parse_xml(xml_str: &str) -> Result<Element, String> {
    let mut parser = XmlParser::new(xml_str);
    parser.parse()
}

struct XmlParser {
    input: Vec<char>,
    pos: usize,
}

impl XmlParser {
    fn new(input: &str) -> Self {
        XmlParser {
            input: input.chars().collect(),
            pos: 0,
        }
    }

    fn parse(&mut self) -> Result<Element, String> {
        self.skip_whitespace_and_comments();

        if self.current() != '<' {
            if self.pos >= self.input.len() {
                return Err("the document does not have a root node".to_string());
            }
            return Err("Expected '<' at start of element".to_string());
        }

        self.parse_element()
    }

    fn current(&self) -> char {
        if self.pos >= self.input.len() {
            '\0'
        } else {
            self.input[self.pos]
        }
    }

    fn peek(&self, offset: usize) -> char {
        let p = self.pos + offset;
        if p >= self.input.len() {
            '\0'
        } else {
            self.input[p]
        }
    }

    fn advance(&mut self) {
        self.pos += 1;
    }

    fn skip_whitespace_and_comments(&mut self) {
        while self.pos < self.input.len() {
            if self.current().is_whitespace() {
                self.advance();
            } else if self.current() == '<' && self.peek(1) == '!' && self.peek(2) == '-' && self.peek(3) == '-' {
                // Skip comment
                self.advance(); // <
                self.advance(); // !
                self.advance(); // -
                self.advance(); // -
                while self.pos + 2 < self.input.len() {
                    if self.current() == '-' && self.peek(1) == '-' && self.peek(2) == '>' {
