        self.parse_element()
    }

    fn current(&self) -> char {
        if self.pos >= self.input.len() {
            '\0'
        } else {
            self.input[self.pos]
        }
    }

    fn peek(&self, offset: usize) -> char {
        let p = self.pos + offset;
        if p >= self.input.len() {
            '\0'
        } else {
            self.input[p]
        }
    }

    fn advance(&mut self) {
        self.pos += 1;
    }

    fn skip_whitespace_and_comments(&mut self) {
        while self.pos < self.input.len() {
            if self.current().is_whitespace() {
                self.advance();
            } else if self.current() == '<' && self.peek(1) == '!' && self.peek(2) == '-' && self.peek(3) == '-' {
                // Skip comment
                self.advance(); // <
                self.advance(); // !
                self.advance(); // -
                self.advance(); // -
                while self.pos + 2 < self.input.len() {
                    if self.current() == '-' && self.peek(1) == '-' && self.peek(2) == '>' {
                        self.advance();
                        self.advance();
                        self.advance();
                        break;
                    }
                    self.advance();
                }
                self.skip_whitespace_and_comments();
            } else if self.current() == '<' && self.peek(1) == '?' {
                // Skip XML declaration
                while self.pos < self.input.len() && !(self.current() == '?' && self.peek(1) == '>') {
                    self.advance();
                }
                if self.pos + 1 < self.input.len() {
                    self.advance();
                    self.advance();
                }
                self.skip_whitespace_and_comments();
            } else {
                break;
            }
        }
    }

    fn parse_element(&mut self) -> Result<Element, String> {
        self.skip_whitespace_and_comments();

        if self.current() != '<' {
            return Err("Expected '<'".to_string());
        }

        self.advance(); // <

        if self.current() == '/' {
            return Err("Unexpected closing tag".to_string());
        }

        if self.current() == '?' || self.current() == '!' {
            // Skip processing instruction or doctype
            while self.pos < self.input.len() && self.current() != '>' {
                self.advance();
            }
            if self.current() == '>' {
                self.advance();
            }
            self.skip_whitespace_and_comments();
            return self.parse_element();
        }

        // Parse element name and attributes
        let tag_name = self.read_identifier()?;
        let mut element = Element::new(tag_name.clone());

        self.skip_whitespace();

        // Parse attributes
        while self.current() != '>' && self.current() != '/' {
            if self.current().is_whitespace() {
                self.skip_whitespace();
            } else {
                let attr_name = self.read_identifier()?;
                self.skip_whitespace();

                if self.current() != '=' {
                    return Err(format!("Expected '=' after attribute name '{}'", attr_name));
                }
                self.advance(); // =

                self.skip_whitespace();

                let attr_value = self.read_quoted_string()?;
                element.attributes.insert(attr_name, attr_value);
            }
        }

        // Check for self-closing tag
        if self.current() == '/' {
            self.advance(); // /
            if self.current() != '>' {
                return Err("Expected '>' after '/'".to_string());
            }
            self.advance(); // >
            return Ok(element);
        }

        if self.current() != '>' {
            return Err("Expected '>'".to_string());
        }
        self.advance(); // >

        // Parse content and children
        let mut text = String::new();

        loop {
            self.skip_whitespace_and_comments();

            if self.current() == '<' {
                if self.peek(1) == '/' {
                    // Closing tag
                    self.advance(); // <
                    self.advance(); // /
                    let close_tag = self.read_identifier()?;
                    self.skip_whitespace();
                    if self.current() != '>' {
                        return Err("Expected '>' after closing tag".to_string());
                    }
                    self.advance(); // >

                    if close_tag != element.name {
                        return Err(format!("Tag mismatch: expected '{}', got '{}'", element.name, close_tag));
                    }

                    element.text = text.trim().to_string();
                    break;
                } else {
                    // Child element
                    if !text.is_empty() && !text.trim().is_empty() {
                        element.text = text.clone();
                        text.clear();
                    }
                    match self.parse_element() {
                        Ok(child) => element.children.push(child),
                        Err(e) => return Err(e),
                    }
                }
            } else if self.current() == '\0' {
                return Err(format!("Unclosed tag: '{}'", element.name));
            } else {
                // Text content
                while self.pos < self.input.len() && self.current() != '<' {
                    text.push(self.current());
                    self.advance();
                }
            }
        }

        Ok(element)
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.current().is_whitespace() {
            self.advance();
        }
    }

    fn read_identifier(&mut self) -> Result<String, String> {
        let mut ident = String::new();
        while self.pos < self.input.len() {
            let c = self.current();
            if c.is_alphanumeric() || c == '_' || c == '-' || c == ':' {
                ident.push(c);
                self.advance();
            } else {
                break;
            }
        }

        if ident.is_empty() {
            Err("Expected identifier".to_string())
        } else {
            Ok(ident)
        }
    }

    fn read_quoted_string(&mut self) -> Result<String, String> {
        let quote = self.current();
        if quote != '"' && quote != '\'' {
            return Err("Expected quote".to_string());
        }
        self.advance();

        let mut value = String::new();
        while self.pos < self.input.len() && self.current() != quote {
            if self.current() == '&' {
                // Handle entity
                value.push_str(&self.parse_entity()?);
            } else {
                value.push(self.current());
            }
            self.advance();
        }

        if self.current() != quote {
            return Err("Unterminated string".to_string());
        }
        self.advance();

        Ok(value)
    }

    fn parse_entity(&mut self) -> Result<String, String> {
        self.advance(); // &
        let mut entity = String::new();

        while self.pos < self.input.len() && self.current() != ';' {
            entity.push(self.current());
            self.advance();
        }

        if self.current() == ';' {
            self.advance();
        }

        match entity.as_str() {
            "lt" => Ok("<".to_string()),
            "gt" => Ok(">".to_string()),
            "amp" => Ok("&".to_string()),
            "quot" => Ok("\"".to_string()),
            "apos" => Ok("'".to_string()),
            _ => Ok(format!("&{};", entity)),
        }
    }
}
