            .to_string();

        let peripherals_elem = root.get_child("peripherals")
            .ok_or(format!("Parsing device `{}` at 2:1\n    Expected a <peripherals> tag, found none", name))?;

        let peripherals = self.parse_peripherals(peripherals_elem)?;

        Ok(Device {
