            version: root.get_child("version").map(|e| e.get_text().to_string()),
            description: root.get_child("description").map(|e| e.get_text().to_string()),
            address_unit_bits: root.get_child("addressUnitBits")
                .map(|e| parse_u32(e.get_text()).unwrap_or(8))
                .unwrap_or(8),
            max_nr_interrupts: root.get_child("maxNrInterrupts")
                .and_then(|e| parse_u32(e.get_text()).ok()),
            vendor: root.get_child("vendor").map(|e| e.get_text().to_string()),
            vendor_id: root.get_child("vendorID").map(|e| e.get_text().to_string()),
            series: root.get_child("series").map(|e| e.get_text().to_string()),
            contact: root.get_child("contact").map(|e| e.get_text().to_string()),
            license: root.get_child("license").map(|e| e.get_text().to_string()),
            license_text: root.get_child("licenseText").map(|e| e.get_text().to_string()),
            peripherals,
        })
    }

    fn parse_peripherals(&self, peripherals_elem: &Element) -> Result<Vec<Peripheral>, String> {
        let mut peripherals = Vec::new();
        for child in &peripherals_elem.children {
