                }
            }
        }

        Ok(Register {
            name,
            display_name: elem.get_child("displayName").map(|e| e.get_text().to_string()),
            description: elem.get_child("description").map(|e| e.get_text().to_string()),
            address_offset,
            size: elem.get_child("size").and_then(|e| parse_u32(e.get_text()).ok()),
            access: elem.get_child("access").map(|e| e.get_text().to_string()),
            reset_value: elem.get_child("resetValue").and_then(|e| parse_u64(e.get_text()).ok()),
            reset_mask: elem.get_child("resetMask").and_then(|e| parse_u64(e.get_text()).ok()),
            fields,
        })
    }

    fn parse_cluster(&self, elem: &Element) -> Result<Cluster, String> {
        let name = elem.get_child("name")
            .ok_or("Missing 'name' in cluster")?
            .get_text()
            .to_string();

        let address_offset = elem.get_child("addressOffset")
            .ok_or("Missing 'addressOffset' in cluster")?
            .get_text();
        let address_offset = parse_u32(address_offset)?;

        let mut registers = Vec::new();
        if let Some(reg_node) = elem.get_child("registers") {
            for child in &reg_node.children {
                if child.name == "register" {
                    registers.push(self.parse_register(child)?);
                }
            }
        }

        Ok(Cluster {
            name,
            description: elem.get_child("description").map(|e| e.get_text().to_string()),
            address_offset,
            size: elem.get_child("size").and_then(|e| parse_u32(e.get_text()).ok()),
            registers,
        })
    }

    fn parse_field(&self, elem: &Element) -> Result<Field, String> {
        let name = elem.get_child("name")
            .ok_or("Missing 'name' in field")?
            .get_text()
            .to_string();

        let bit_offset = elem.get_child("bitOffset")
            .ok_or("Missing 'bitOffset' in field")?
            .get_text();
        let bit_offset = parse_u32(bit_offset)?;

        let bit_width = elem.get_child("bitWidth")
            .ok_or("Missing 'bitWidth' in field")?
            .get_text();
        let bit_width = parse_u32(bit_width)?;

        let mut enumerated_values = Vec::new();
        if let Some(ev_elem) = elem.get_child("enumeratedValues") {
            for child in &ev_elem.children {
                if child.name == "enumeratedValue" {
                    enumerated_values.push(self.parse_enumerated_value(child)?);
                }
            }
        }

        Ok(Field {
            name,
            description: elem.get_child("description").map(|e| e.get_text().to_string()),
            bit_offset,
            bit_width,
            access: elem.get_child("access").map(|e| e.get_text().to_string()),
            reset_value: elem.get_child("resetValue").and_then(|e| parse_u64(e.get_text()).ok()),
            read_action: elem.get_child("readAction").map(|e| e.get_text().to_string()),
            modified_write_values: elem.get_child("modifiedWriteValues").map(|e| e.get_text().to_string()),
            write_constraint: None,
            enumerated_values,
        })
    }

    fn parse_enumerated_value(&self, elem: &Element) -> Result<EnumeratedValue, String> {
        Ok(EnumeratedValue {
            name: elem.get_child("name").map(|e| e.get_text().to_string()),
            description: elem.get_child("description").map(|e| e.get_text().to_string()),
            value: elem.get_child("value").and_then(|e| parse_u64(e.get_text()).ok()),
            is_default: elem.get_attribute("isDefault").map(|v| v == "true").unwrap_or(false),
        })
    }
}

fn parse_u32(s: &str) -> Result<u32, String> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        u32::from_str_radix(&s[2..], 16).map_err(|_| format!("Invalid u32: {}", s))
    } else {
        s.parse::<u32>().map_err(|_| format!("Invalid u32: {}", s))
    }
}

fn parse_u64(s: &str) -> Result<u64, String> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        u64::from_str_radix(&s[2..], 16).map_err(|_| format!("Invalid u64: {}", s))
    } else {
        s.parse::<u64>().map_err(|_| format!("Invalid u64: {}", s))
    }
}
