        output.push_str("#[doc = r\"Common register and bit access and modify traits\"]\npub mod generic {\n");
        output.push_str(GENERIC_MODULE);
        output.push_str("\n}\n");
    }

    // Generate peripheral modules
    output.push_str("\n");
    for peripheral in &device.peripherals {
        let desc = peripheral.description.as_ref().map(|s| s.clone()).unwrap_or_else(|| "".to_string());
        let mod_name = peripheral.name.to_lowercase();
        output.push_str(&format!("#[doc = \"{}\"]\npub mod {} {{\n", desc, mod_name));
        output.push_str("    use super::generic::*;\n");
        output.push_str("}\n");
    }

    Ok(output)
}

